106:         String command = getCommand();
107:         Arguments args = getArguments();
108:         Arguments environment = getEnvironmentVariables();
109:         boolean checkReturnCode = getCheckReturnCode();
110:         int expectedReturnCode = getExpectedReturnCode();
111:         List<String> cmds = new ArrayList<>(args.getArgumentCount() + 1);
112:         StringBuilder cmdLine = new StringBuilder((null == command) ? "" : command);
113:         cmds.add(command);
114:         for (int i=0;i<args.getArgumentCount();i++) {
115:             Argument arg = args.getArgument(i);
116:             cmds.add(arg.getValue());
117:             cmdLine.append(" ");
