145: 
146:         results.setSamplerData("Working Directory: "+directory.getAbsolutePath()+
147:                 "\nEnvironment: "+env+
148:                 "\nExecuting: " + cmdLine.toString());
149: 
150:         SystemCommand nativeCommand = null;
151:         try {
152:             nativeCommand = new SystemCommand(directory, getTimeout(), 0, env, getStdin(), getStdout(), getStderr());
153:             results.sampleStart();
154:             int returnCode = nativeCommand.run(cmds);
155:             results.sampleEnd();
156:             results.setResponseCode(Integer.toString(returnCode));
157:             if(log.isDebugEnabled()) {
158:                 log.debug("Ran : "+cmdLine + " using working directory: "+directory.getAbsolutePath()+
159:                         " with execution environment: "+nativeCommand.getExecutionEnvironment()+ " => " + returnCode);
160:             }
