162:             if (checkReturnCode && (returnCode != expectedReturnCode)) {
163:                 results.setSuccessful(false);
164:                 results.setResponseMessage("Unexpected return code.  Expected ["+expectedReturnCode+"]. Actual ["+returnCode+"].");
165:             } else {
