136:     // helper method to allow input and output to be changed for chaining
137:     private int run(List<String> arguments, InputStream in,
138:             OutputStream out,OutputStream err) throws InterruptedException, IOException, TimeoutException {
139:         Process proc = null;
140:         final ProcessBuilder procBuild = new ProcessBuilder(arguments);
141:         if (env != null) {
142:             procBuild.environment().putAll(env);
143:         }
144:         this.executionEnvironment = Collections.unmodifiableMap(procBuild.environment());
145:         procBuild.directory(directory);
146:         if (err == null) {
147:             procBuild.redirectErrorStream(true);
148:         }
149:         try
150:         {
151:             proc = procBuild.start();
152: 
153:             final OutputStream procOut = proc.getOutputStream();
154:             final InputStream procErr = proc.getErrorStream();
155:             final InputStream procIn = proc.getInputStream();
156: 
157:             final StreamCopier swerr;
158:             if (err != null){
159:                 swerr = new StreamCopier(procErr, err);
160:                 swerr.start();
161:             } else {
162:                 swerr = null;
163:             }
164: 
165:             final StreamCopier swout = new StreamCopier(procIn, out);
166:             swout.start();
167: 
168:             final StreamCopier swin;
169:             if (in != null) {
170:                 swin = new StreamCopier(in, procOut);
171:                 swin.start();
172:             } else {
173:                 swin = null;
174:                 procOut.close(); // ensure the application does not hang if it requests input
175:             }
176:             int exitVal = waitForEndWithTimeout(proc, timeoutMillis);
177: 
178:             swout.join();
179:             if (swerr != null) {
180:                 swerr.join();
181:             }
182:             if (swin != null) {
183:                 swin.interrupt(); // the copying thread won't generally detect EOF
184:                 swin.join();
185:             }
186:             procErr.close();
187:             procIn.close();
188:             procOut.close();
189:             return exitVal;
190:         } finally {
191:             if(proc != null) {
192:                 try {
193:                     proc.destroy();
194:                 } catch (Exception ignored) {
195:                     // Ignored
196:                 }
197:             }
198:         }
