211:     public int run(List<String> arguments1, List<String> arguments2) throws InterruptedException, IOException, TimeoutException {
212:         ByteArrayOutputStream out = new ByteArrayOutputStream(); // capture the intermediate output
213:         int exitCode = run(arguments1, stdin, out, stderr);
214:         if (exitCode == 0) {
215:             exitCode = run(arguments2, new ByteArrayInputStream(out.toByteArray()), stdout, stderr);
216:         }
