222:      * @param proc Process
223:      * @param timeoutInMillis long timeout in ms
224:      * @return proc exit value
225:      * @throws TimeoutException when timeout is reached while execution
226:      */
227:     private static int waitForEndWithTimeout(Process proc, long timeoutInMillis) throws InterruptedException, TimeoutException {
228:         if (timeoutInMillis <= 0L) {
229:             return proc.waitFor();
230:         }
231:         if (proc.waitFor(timeoutInMillis, TimeUnit.MILLISECONDS)) {
232:             return proc.exitValue();
