57:     /** The directory JMeter is installed in. */
58:     private static final String JMETER_INSTALLATION_DIRECTORY;
59: 
60:     private static final List<Exception> EXCEPTIONS_IN_INIT = new ArrayList<>();
61: 
62:     static {
63:         final List<URL> jars = new ArrayList<>();
64:         final String initiaClasspath = System.getProperty(JAVA_CLASS_PATH);
65: 
66:         // Find JMeter home dir from the initial classpath
67:         String tmpDir;
68:         StringTokenizer tok = new StringTokenizer(initiaClasspath, File.pathSeparator);
69:         if (tok.countTokens() == 1
70:                 || (tok.countTokens()  == 2 // Java on Mac OS can add a second entry to the initial classpath
71:                     && OS_NAME_LC.startsWith("mac os x")// $NON-NLS-1$
72:                    )
73:            ) {
74:             File jar = new File(tok.nextToken());
75:             try {
76:                 tmpDir = jar.getCanonicalFile().getParentFile().getParent();
77:             } catch (IOException e) {
78:                 tmpDir = null;
79:             }
80:         } else {// e.g. started from IDE with full classpath
81:             tmpDir = System.getProperty("jmeter.home", System.getenv("JMETER_HOME"));// Allow override $NON-NLS-1$ $NON-NLS-2$
82:             if (tmpDir == null || tmpDir.isEmpty()) {
83:                 File userDir = new File(System.getProperty("user.dir"));// $NON-NLS-1$
84:                 tmpDir = userDir.getAbsoluteFile().getParent();
85:             }
86:         }
87:         if (tmpDir == null) {
88:             tmpDir = System.getenv("JMETER_HOME");
89:         }
90:         JMETER_INSTALLATION_DIRECTORY=tmpDir;
91: 
92:         // Does the system support UNC paths? If so, may need to fix them up later
93:         boolean usesUNC = OS_NAME_LC.startsWith("windows");// $NON-NLS-1$
94: 
95:         // Add standard jar locations to initial classpath
96:         StringBuilder classpath = new StringBuilder();
97:         File[] libDirs = new File[] { new File(JMETER_INSTALLATION_DIRECTORY + File.separator + "lib"),// $NON-NLS-1$ $NON-NLS-2$
98:                 new File(JMETER_INSTALLATION_DIRECTORY + File.separator + "lib" + File.separator + "ext"),// $NON-NLS-1$ $NON-NLS-2$
99:                 new File(JMETER_INSTALLATION_DIRECTORY + File.separator + "lib" + File.separator + "junit")};// $NON-NLS-1$ $NON-NLS-2$
100:         for (File libDir : libDirs) {
101:             File[] libJars = libDir.listFiles((dir, name) -> name.endsWith(".jar"));
102:             if (libJars == null) {
103:                 new Throwable("Could not access " + libDir).printStackTrace(); // NOSONAR No logging here
104:                 continue;
105:             }
106:             Arrays.sort(libJars); // Bug 50708 Ensure predictable order of jars
107:             for (File libJar : libJars) {
108:                 try {
109:                     String s = libJar.getPath();
110: 
111:                     // Fix path to allow the use of UNC URLs
112:                     if (usesUNC) {
113:                         if (s.startsWith("\\\\") && !s.startsWith("\\\\\\")) {// $NON-NLS-1$ $NON-NLS-2$
114:                             s = "\\\\" + s;// $NON-NLS-1$
115:                         } else if (s.startsWith("//") && !s.startsWith("///")) {// $NON-NLS-1$ $NON-NLS-2$
116:                             s = "//" + s;// $NON-NLS-1$
117:                         }
118:                     } // usesUNC
