120:                     jars.add(new File(s).toURI().toURL());// See Java bug 4496398
121:                     classpath.append(CLASSPATH_SEPARATOR);
122:                     classpath.append(s);
123:                 } catch (MalformedURLException e) { // NOSONAR
124:                     EXCEPTIONS_IN_INIT.add(new Exception("Error adding jar:"+libJar.getAbsolutePath(), e));
125:                 }
126:             }
127:         }
128: 
129:         // ClassFinder needs the classpath
130:         System.setProperty(JAVA_CLASS_PATH, initiaClasspath + classpath.toString());
131:         loader = createClassLoader(jars);
