134:     @SuppressWarnings("removal")
135:     private static DynamicClassLoader createClassLoader(List<URL> jars) {
136:         return java.security.AccessController.doPrivileged(
137:                 (java.security.PrivilegedAction<DynamicClassLoader>) () ->
138:                         new DynamicClassLoader(jars.toArray(new URL[jars.size()]))
139:         );
