1: /**
2:  * harmony-mirror.js — is a third-party package already adapted to HarmonyOS PC?
3:  *
4:  * Two source kinds (see HARMONY_MIRRORS):
5:  *  - Python ('simple'): the mirror is a full PyPI proxy, so mere presence ≠ ported.
6:  *    The real signal is a native `ohos` wheel (numpy ships `*-ohos_aarch64.whl`). The
7:  *    mirror has NO listable root (it 404s), so we probe each package page on demand:
8:  *    GET <simple>/<name>/ : 200 AND contains an `ohos` wheel ⇒ adapted.
9:  *  - C/C++ ('list'): the OpenHarmony cmd-pkgs README lists every prebuilt package in
10:  *    its install commands (`sh -s -- <name> <ver>`); membership (with name variants)
11:  *    ⇒ adapted.
12:  * Both kinds cache to .harmony-mirror-cache.json — per-package for 'simple', and
13:  * the per-package result (.harmony-mirror-cache.json). Single source of truth
14:  * shared by the web panel (server require()s this) and the analyzer agent (via
15:  * scripts/harmony_adapted.js).
16:  *
17:  * Zero-dependency: Node https. TLS works in Node even where the system Python
18:  * cert store does not.
19:  */
20: 'use strict';
21: 
22: const https = require('https');
23: const fs = require('fs');
24: const path = require('path');
25: 
26: // ecosystem (canonical, per server ecoNorm) -> how to check the OpenHarmony PC source.
27: //  - kind 'simple': PEP 503 per-package probe (PyPI mirror; ohos wheel ⇒ adapted).
28: //  - kind 'list'  : one README listing all prebuilt packages; membership ⇒ adapted.
29: const HARMONY_MIRRORS = {
30:   python: { kind: 'simple', url: 'https://pypi.cnb.cool/OpenHarmonyPCDeveloper/pypi/-/packages/simple/' },
31:   cpp: { kind: 'list', url: 'https://raw.gitcode.com/OpenHarmonyPCDeveloper/cmd-pkgs/raw/main/README.md', listKey: 'cpp' },
32:   c: { kind: 'list', url: 'https://raw.gitcode.com/OpenHarmonyPCDeveloper/cmd-pkgs/raw/main/README.md', listKey: 'cpp' },
33: };
34: const MIRROR_LABEL = {
35:   python: 'OpenHarmony PC PyPI 镜像 (pypi.cnb.cool/OpenHarmonyPCDeveloper)',
36:   cpp: 'OpenHarmony PC C/C++ 预编译包 (gitcode.com/OpenHarmonyPCDeveloper/cmd-pkgs)',
37:   c: 'OpenHarmony PC C/C++ 预编译包 (gitcode.com/OpenHarmonyPCDeveloper/cmd-pkgs)',
38: };
39: 
40: const CACHE_FILE = path.join(__dirname, '..', '.harmony-mirror-cache.json');
41: const CACHE_TTL_MS = 3 * 24 * 3600 * 1000;
42: const TIMEOUT = 8000;
43: const MAX_CONCURRENCY = 5;
44: let cache = null;   // { "eco:normname": { adapted, ts } }
45: 
46: // PEP 503 normalized project name.
47: function normalize(name) {
48:   return String(name || '').replace(/[-_.]+/g, '-').trim().toLowerCase();
49: }
50: 
51: function loadCache() {
52:   if (cache) return cache;
53:   try { cache = JSON.parse(fs.readFileSync(CACHE_FILE, 'utf8')); } catch { cache = {}; }
54:   return cache;
55: }
56: function saveCache() {
57:   try { fs.writeFileSync(CACHE_FILE, JSON.stringify(cache)); } catch (_) {}
58: }
59: 
60: // GET returning { status, body } (does NOT throw on 4xx — 404 is a real answer).
61: function httpGet(url, redirects = 1) {
62:   return new Promise((resolve, reject) => {
63:     const req = https.get(url, { headers: { 'User-Agent': 'pc-lib-analysis/1.0' } }, (res) => {
64:       const { statusCode, headers } = res;
65:       if (statusCode >= 300 && statusCode < 400 && headers.location && redirects > 0) {
66:         res.resume();
67:         return resolve(httpGet(new URL(headers.location, url).toString(), redirects - 1));
68:       }
69:       let body = '';
70:       res.setEncoding('utf8');
71:       res.on('data', (c) => (body += c));
72:       res.on('end', () => resolve({ status: statusCode, body }));
73:     });
74:     req.on('error', reject);
75:     req.setTimeout(TIMEOUT, () => req.destroy(new Error('timeout')));
76:   });
77: }
78: 
79: // 'simple' strategy: probe one package page; returns boolean or null (error/unknown).
80: async function probe(cfg, name) {
81:   const url = cfg.url + normalize(name) + '/';
82:   let r;
83:   try { r = await httpGet(url); } catch { return null; }
84:   if (r.status === 404) return false;
85:   if (r.status < 200 || r.status >= 300) return null;
86:   // The mirror is a full PyPI proxy (most packages are plain upstream passthrough).
87:   // The HarmonyOS-port signal is a native `ohos` wheel (e.g. *-ohos_aarch64.whl);
88:   // pure passthrough packages have none. So require an ohos artifact.
89:   return /ohos/i.test(r.body);
90: }
91: 
92: // 'list' strategy: fetch the cmd-pkgs README once, harvest every prebuilt package
93: // name from its install commands (`sh -s -- <name> <version>`), cache as a Set.
94: async function adaptedList(cfg, refresh = false) {
95:   const c = loadCache();
96:   const cacheKey = `_list:${cfg.listKey}`;
97:   const entry = c[cacheKey];
98:   if (!refresh && entry && Date.now() - (entry.ts || 0) < CACHE_TTL_MS) return new Set(entry.names || []);
99:   let r;
100:   try { r = await httpGet(cfg.url); } catch { return entry ? new Set(entry.names) : null; }
101:   if (!r || r.status < 200 || r.status >= 300) return entry ? new Set(entry.names) : null;
102:   const names = new Set();
103:   const re = /sh\s+-s\s+--\s+([a-z0-9._+-]+)/gi;
104:   let m;
105:   while ((m = re.exec(r.body))) names.add(m[1].toLowerCase());
106:   c[cacheKey] = { names: [...names], ts: Date.now() };
107:   saveCache();
108:   return names;
109: }
110: 
111: // C/C++ dep names rarely match the list verbatim; try a few harmless variants.
112: function nameVariants(name) {
113:   const n = normalize(name);
114:   const v = new Set([n]);
115:   v.add(n.replace(/^lib/, ''));     // libpng -> png
116:   v.add('lib' + n);                 // png -> libpng
117:   v.add(n.replace(/\d+$/, ''));     // eigen3 -> eigen, sqlite3 -> sqlite
118:   v.delete('');
119:   return [...v];
120: }
121: 
122: // adapted bool for one package, with disk cache (null results are not cached).
123: async function isAdapted(ecoCanon, name, refresh = false) {
124:   const eco = String(ecoCanon || '').toLowerCase();
125:   const cfg = HARMONY_MIRRORS[eco];
126:   if (!cfg) return false;
127:   const c = loadCache();
128:   const key = `${eco}:${normalize(name)}`;
129:   const hit = c[key];
130:   if (!refresh && hit && Date.now() - (hit.ts || 0) < CACHE_TTL_MS) return hit.adapted;
131:   let res;
132:   if (cfg.kind === 'list') {
133:     const set = await adaptedList(cfg, refresh);
134:     res = set === null ? null : nameVariants(name).some((v) => set.has(v));
135:   } else {
136:     res = await probe(cfg, name);
137:   }
138:   if (res === null) return hit ? hit.adapted : false;   // keep stale on transient error
139:   c[key] = { adapted: res, ts: Date.now() };
140:   saveCache();
141:   return res;
142: }
143: 
144: // Resolve many names with bounded concurrency.
145: async function _mapLimited(items, fn) {
146:   const out = new Array(items.length);
147:   let i = 0;
148:   const workers = Array.from({ length: Math.min(MAX_CONCURRENCY, items.length || 1) }, async () => {
149:     while (i < items.length) { const idx = i++; out[idx] = await fn(items[idx], idx); }
150:   });
151:   await Promise.all(workers);
152:   return out;
153: }
154: 
155: // { ecosystem, source, results: {name:{adapted,source}}, adaptedCount, total }
156: async function statusFor(ecoCanon, names, refresh = false) {
157:   const eco = String(ecoCanon || '').toLowerCase();
158:   const src = MIRROR_LABEL[eco] || null;
159:   const flags = await _mapLimited(names, (nm) => isAdapted(eco, nm, refresh));
160:   const results = {};
161:   let adaptedCount = 0;
162:   names.forEach((nm, k) => {
163:     const hit = !!flags[k];
164:     if (hit) adaptedCount++;
165:     results[nm] = { adapted: hit, source: hit ? src : null };
166:   });
167:   return { ecosystem: eco, source: src, results, adaptedCount, total: names.length };
168: }
169: 
170: // Stamp dependencies[].harmony_adapted into a report.json in place (Phase 2 / agent).
171: async function stampReport(reportPath) {
172:   const rep = JSON.parse(fs.readFileSync(reportPath, 'utf8'));
173:   const deps = ((rep.dependencies || {}).dependencies) || [];
174:   await _mapLimited(deps, async (d) => {
175:     if (!d || !d.name) return;
176:     const eco = String(d.ecosystem || '').toLowerCase();
177:     const hit = await isAdapted(eco, d.name);
178:     d.harmony_adapted = hit;
179:     d.harmony_adapted_source = hit ? (MIRROR_LABEL[eco] || null) : null;
180:   });
181:   const stamped = deps.filter((d) => d && d.harmony_adapted).length;
182:   fs.writeFileSync(reportPath, JSON.stringify(rep, null, 2));
183:   return { stamped, total: deps.length };
184: }
185: 
186: module.exports = { isAdapted, statusFor, stampReport, normalize, HARMONY_MIRRORS, MIRROR_LABEL };

