37: /**
38:  * Configures undo manager for a text component.
39:  */
40: @API(since = "5.3", status = API.Status.INTERNAL)
41: public class TextComponentUI {
42:     private static final String OS_NAME = System.getProperty("os.name");// $NON-NLS-1$
43: 
44:     private static final boolean IS_MAC =
45:             Pattern.compile("mac os x|darwin|osx", Pattern.CASE_INSENSITIVE)
46:                     .matcher(OS_NAME)
47:                     .find();
48: 
49:     private static final int COMMAND_KEY =
50:             IS_MAC ? InputEvent.META_DOWN_MASK : InputEvent.CTRL_DOWN_MASK;
51: 
52:     @API(since = "5.3", status = API.Status.INTERNAL)
53:     public static final TextComponentUI INSTANCE = new TextComponentUI();
54: 
55:     private final AtomicInteger undoEpoch = new AtomicInteger();
56: 
57:     /**
58:      * Causes all undo managers to invalidate their history.
59:      */
60:     @API(since = "5.3", status = API.Status.INTERNAL)
61:     public void resetUndoHistory() {
62:         undoEpoch.getAndIncrement();
63:     }
64: 
65:     /**
66:      * Installs an undo manager and keyboard shortcuts to a text component
67:      * @param component JTextField or JTextArea
68:      */
69:     @API(since = "5.3", status = API.Status.INTERNAL)
70:     public void installUndo(JTextComponent component) {
71:         // JMeter reuses Swing JComponents, so when user switches to another component,
72:         // JComponent#name is updated. However, we don't want user to be able to "undo" that
73:         // So when tree selection is changed, we increase undoEpoch. That enables
74:         // UndoManagers to treat that as "end of undo history"
75:         UndoManager manager = new DefaultUndoManager(undoEpoch);
76:         manager.setLimit(200);
77:         component.addPropertyChangeListener("document",
78:                 new AddUndoableEditListenerPropertyChangeListener(manager));
79:         component.getActionMap().put("undo", new AbstractAction() {
80:             @Override
81:             public void actionPerformed(ActionEvent e) {
82:                 if (manager.canUndo()) {
83:                     manager.undo();
84:                 }
85:             }
86:         });
87:         component.getActionMap().put("redo", new AbstractAction() {
88:             @Override
89:             public void actionPerformed(ActionEvent e) {
90:                 if (manager.canRedo()) {
91:                     manager.redo();
92:                 }
93:             }
94:         });
95: 
96:         KeyStroke commandZ = KeyStroke.getKeyStroke(KeyEvent.VK_Z, COMMAND_KEY);
97:         component.getInputMap().put(commandZ, "undo");
98:         KeyStroke shiftCommandZ = KeyStroke.getKeyStroke(KeyEvent.VK_Z, COMMAND_KEY | InputEvent.SHIFT_DOWN_MASK);
99:         component.getInputMap().put(shiftCommandZ, "redo");
100:     }
101: 
102:     /**
103:      * Removes the default undo manager.
104:      * By default, JMeter installs undo manager to all text fields via {@code Swing -> createUI},
105:      * however, undo is not always needed (e.g. log panel), so here's an API to remove it.
106:      * @param component JTextField or JTextArea
107:      */
108:     @API(since = "5.5", status = API.Status.INTERNAL)
109:     public static void uninstallUndo(JTextComponent component) {
110:         List<PropertyChangeListener> listenersToRemove = new ArrayList<>();
111:         for (PropertyChangeListener listener : component.getPropertyChangeListeners("document")) {
112:             if (listener instanceof AddUndoableEditListenerPropertyChangeListener v) {
113:                 listenersToRemove.add(v);
114: 
115:                 UndoManager undoManager = v.getUndoManager();
116:                 undoManager.discardAllEdits();
117:                 Document document = component.getDocument();
118:                 if (document != null) {
119:                     document.removeUndoableEditListener(undoManager);
120:                 }
121:             }
122:         }
123:         for (PropertyChangeListener listener : listenersToRemove) {
124:             component.removePropertyChangeListener("document", listener);
125:         }
126:     }
127: }

