44: /**
45:  * Restart JMeter
46:  * Based on https://dzone.com/articles/programmatically-restart-java
47:  * @since 5.0
48:  */
49: @AutoService({
50:         Command.class,
51:         MenuCreator.class
52: })
53: public class Restart extends AbstractActionWithNoRunningTest implements MenuCreator {
54:     private static final Logger log = LoggerFactory.getLogger(Restart.class);
55: 
56:     /**
57:      * Sun property pointing the main class and its arguments.
58:      * Might not be defined on non Hotspot VM implementations.
59:      */
60:     public static final String SUN_JAVA_COMMAND = "sun.java.command";
61: 
62:     private static final Set<String> commands = new HashSet<>();
63: 
64:     static {
65:         commands.add(ActionNames.RESTART);
66:     }
67: 
68:     /**
69:      * @see Command#doAction(ActionEvent)
70:      */
71:     @Override
72:     public void doActionAfterCheck(ActionEvent e) {
73:         try {
74:             GuiPackage guiPackage = GuiPackage.getInstance();
75:             ActionRouter.getInstance().doActionNow(new ActionEvent(e.getSource(), e.getID(), ActionNames.CHECK_DIRTY));
76:             if (guiPackage.isDirty()) {
77:                 int chosenOption =
78:                         JOptionPane.showConfirmDialog(guiPackage.getMainFrame(), JMeterUtils
79:                                 .getResString("cancel_exit_to_save"), // $NON-NLS-1$
80:                                 JMeterUtils.getResString("save?"), // $NON-NLS-1$
81:                                 JOptionPane.YES_NO_CANCEL_OPTION, JOptionPane.QUESTION_MESSAGE);
82:                 if (chosenOption == JOptionPane.NO_OPTION) {
83:                     restartApplication(null);
84:                 } else if (chosenOption == JOptionPane.YES_OPTION) {
85:                     ActionRouter.getInstance().doActionNow(new ActionEvent(e.getSource(), e.getID(), ActionNames.SAVE));
86:                     if (!guiPackage.isDirty()) {
87:                         restartApplication(null);
88:                     }
89:                 }
90:             } else {
91:                 restartApplication(null);
92:             }
93:         } catch (Exception ex) {
94:             log.error("Error trying to restart: {}", ex.getMessage(), ex);
95:             JOptionPane.showMessageDialog(GuiPackage.getInstance().getMainFrame(),
96:                     JMeterUtils.getResString("restart_error")+":\n" + ex.getLocalizedMessage(),  //$NON-NLS-1$  //$NON-NLS-2$
97:                     JMeterUtils.getResString("error_title"), JOptionPane.ERROR_MESSAGE); //$NON-NLS-1$
98: 
99:         }
100:     }
101: 
102:     /**
103:      * Restart the current Java application
104:      *
105:      * @param runBeforeRestart
106:      *            some custom code to be run before restarting
107:      */
108:     public static void restartApplication(Runnable runBeforeRestart) {
109:         String javaCommand = System.getProperty(SUN_JAVA_COMMAND);
110:         List<String> processArgs = new ArrayList<>();
111:         if (StringUtilities.isEmpty(javaCommand)) {
112:             JOptionPane.showMessageDialog(GuiPackage.getInstance().getMainFrame(),
113:                     JMeterUtils.getResString("restart_error")+":\n This command is only supported on Open JDK or Oracle JDK" ,  //$NON-NLS-1$  //$NON-NLS-2$
114:                     JMeterUtils.getResString("error_title"), JOptionPane.ERROR_MESSAGE); //$NON-NLS-1$
115:             return;
116:         }
117:         // java binary
118:         processArgs.add(System.getProperty("java.home") + "/bin/java");
119:         // vm arguments
120:         List<String> vmArguments = ManagementFactory.getRuntimeMXBean().getInputArguments();
121:         for (String arg : vmArguments) {
122:             // if it's the agent argument : we ignore it otherwise the
123:             // address of the old application and the new one will be in
124:             // conflict
125:             if (!arg.contains("-agentlib")) {
126:                 processArgs.add(arg);
127:             }
128:         }
129: 
130:         // program main and program arguments
131:         String[] mainCommand = javaCommand.split(" ");
132:         // program main is a jar
133:         if (mainCommand[0].endsWith(".jar")) {
134:             // if it's a jar, add -jar mainJar
135:             processArgs.add("-jar");
136:             processArgs.add(new File(mainCommand[0]).getPath());
137:         } else {
138:             // else it's a .class, add the classpath and mainClass
139:             processArgs.add("-cp");
140:             processArgs.add(System.getProperty("java.class.path"));
141:             processArgs.add(mainCommand[0]);
142:         }
143:         // finally add program arguments
144:         processRemainingArgs(processArgs, mainCommand);
145:         log.debug("Restart with {} from [{}]", processArgs, javaCommand);
146:         // execute the command in a shutdown hook, to be sure that all the
147:         // resources have been disposed before restarting the application
148:         Runtime.getRuntime().addShutdownHook(new Thread() {
149:             @Override
150:             public void run() {
151:                 try {
152:                     new ProcessBuilder(processArgs).start();
153:                 } catch (IOException e) {
154:                     log.error("Error calling restart command {}", processArgs, e);
155:                 }
156:             }
157:         });
158:         // execute some custom code before restarting
159:         if (runBeforeRestart != null) {
160:             runBeforeRestart.run();
161:         }
162:         // exit
163:         System.exit(0); // NOSONAR Required
164: 
165:     }
