167:     /**
168:      * Try to re-combine the parameters to regard spaces in file names
169:      * <p>
170:      * Java command line has no knowledge of the 'real' parameters and
171:      * we have to do a bit of guessing to re-assemble the parameters with
172:      * spaces and the drop the spaces, that should split the parameters.
173:      * <p>
174:      * So we guess, that each parameter starts with a dash ({@code -}) and
175:      * everything else are values, that should be stitched together.
176:      *
177:      * @param processArgs arguments to be given to ProcessBuilder
178:      * @param mainCommand original command line split at spaces
179:      */
180:     private static void processRemainingArgs(List<? super String> processArgs, String[] mainCommand) {
181:         boolean paramValue = false;
182:         StringBuilder partialParamValue = new StringBuilder();
183:         for (int i = 1; i < mainCommand.length; i++) {
184:             String currentPart = mainCommand[i];
185:             if (paramValue) {
186:                 if (currentPart.startsWith("-")) {
187:                     paramValue = false;
188:                     processArgs.add(partialParamValue.toString());
189:                     partialParamValue.setLength(0);
190:                     processArgs.add(currentPart);
191:                 } else {
192:                     partialParamValue.append(" ");
193:                     partialParamValue.append(currentPart);
194:                 }
195:             } else {
196:                 if (currentPart.startsWith("-")) {
197:                     processArgs.add(currentPart);
198:                 } else {
199:                     paramValue = true;
200:                     partialParamValue.setLength(0);
201:                     partialParamValue.append(currentPart);
202:                 }
203:             }
204:         }
205:         if (paramValue) {
206:             processArgs.add(partialParamValue.toString());
207:         }
208:     }
