226:             menuItemIC.setAccelerator(null);
227:             menuItemIC.addActionListener(ActionRouter.getInstance());
228: 
229:             return new JMenuItem[]{menuItemIC};
230:         }
231:         return new JMenuItem[0];
232:     }
